const API="/api/admin";let token=localStorage.getItem("admin_token");function getHeaders(){return{"Content-Type":"application/json",...token?{Authorization:"Bearer "+token}:{}}}async function adminLogin(){const t=document.getElementById("admin-password").value,e=document.getElementById("login-error");e.style.display="none";try{const n=await fetch(API+"/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password:t})});if(!n.ok)return void(e.style.display="block");const o=await n.json();token=o.token,localStorage.setItem("admin_token",token),document.getElementById("login-screen").style.display="none",document.getElementById("dashboard").style.display="block",loadData()}catch(t){e.textContent="Connection error",e.style.display="block"}}function adminLogout(){token=null,localStorage.removeItem("admin_token"),document.getElementById("dashboard").style.display="none",document.getElementById("login-screen").style.display="flex",document.getElementById("admin-password").value=""}async function loadData(){loadContacts(),loadUsers(),loadOrders()}async function loadContacts(){const t=document.getElementById("contacts-body");try{const e=await fetch(API+"/contacts",{headers:getHeaders()});if(401===e.status)return void adminLogout();const n=await e.json();if(document.getElementById("contacts-count").textContent=n.length,!n.length)return void(t.innerHTML='<tr><td colspan="6"><div class="empty-state"><p>No contact submissions yet</p></div></td></tr>');t.innerHTML=n.map(t=>`<tr>\n                <td class="timestamp">${new Date(t.createdAt).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}</td>\n                <td><strong>${esc(t.name)}</strong></td>\n                <td>${esc(t.phone)}</td>\n                <td><span class="badge badge-${esc(t.service)}">${esc(t.service)}</span></td>\n                <td class="msg-cell" title="${esc(t.address||"")}">${esc(t.address||"—")}</td>\n                <td class="msg-cell" title="${esc(t.message)}">${esc(t.message)}</td>\n            </tr>`).join("")}catch(e){t.innerHTML='<tr><td colspan="6"><div class="empty-state"><p>Failed to load contacts</p></div></td></tr>'}}async function loadUsers(){const t=document.getElementById("users-body");try{const e=await fetch(API+"/users",{headers:getHeaders()});if(401===e.status)return void adminLogout();const n=await e.json();if(document.getElementById("users-count").textContent=n.length,!n.length)return void(t.innerHTML='<tr><td colspan="4"><div class="empty-state"><p>No registered users yet</p></div></td></tr>');t.innerHTML=n.map(t=>`<tr>\n                <td class="timestamp">${new Date(t.createdAt).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}</td>\n                <td><strong>${esc(t.name)}</strong></td>\n                <td>${esc(t.email)}</td>\n                <td>${t.phone?esc(t.phone):'<span style="color:#555">—</span>'}</td>\n            </tr>`).join("")}catch(e){t.innerHTML='<tr><td colspan="4"><div class="empty-state"><p>Failed to load users</p></div></td></tr>'}}async function loadOrders(){const t=document.getElementById("orders-body");try{const e=await fetch(API+"/orders",{headers:getHeaders()});if(401===e.status)return void adminLogout();const n=await e.json();if(document.getElementById("orders-count").textContent=n.length,!n.length)return void(t.innerHTML='<tr><td colspan="8"><div class="empty-state"><p>No orders yet</p></div></td></tr>');const i={cod:"Cash on Delivery",upi:"UPI",netbanking:"Net Banking"};t.innerHTML=n.map(t=>{const e=new Date(t.createdAt).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}),a=(t.items||[]).map(t=>`${esc(t.name)} ×${t.qty}${t.unit?" "+esc(t.unit):""}`).join(", "),r=i[t.paymentMethod]||t.paymentMethod;return `<tr>\n                <td class="timestamp">${e}</td>\n                <td><strong>${esc(t.customerName)}</strong></td>\n                <td>${esc(t.phone)}<br><span style="color:#555;font-size:12px">${esc(t.email||"—")}</span></td>\n                <td class="msg-cell" title="${esc(t.address||"")}">${esc(t.address||"—")}</td>\n                <td class="items-cell" title="${a}">${a||"—"}</td>\n                <td><strong>₹${Number(t.totalAmount).toLocaleString("en-IN")}</strong></td>\n                <td><span class="badge badge-${esc(t.paymentMethod)}">${esc(r)}</span></td>\n                <td><span class="badge badge-${esc(t.orderStatus||"placed")}">${esc(t.orderStatus||"placed")}</span>\n                    <br><span class="badge badge-${esc(t.paymentStatus||"pending")}" style="margin-top:4px">${esc(t.paymentStatus||"pending")}</span></td>\n            </tr>`}).join("")}catch(e){t.innerHTML='<tr><td colspan="8"><div class="empty-state"><p>Failed to load orders</p></div></td></tr>'}}function switchTab(t){document.querySelectorAll(".tab").forEach(t=>t.classList.remove("active")),document.querySelectorAll(".panel").forEach(t=>t.classList.remove("active")),document.querySelector(`.tab[data-tab="${t}"]`).classList.add("active"),document.getElementById(`panel-${t}`).classList.add("active")}function esc(t){const e=document.createElement("div");return e.textContent=t,e.innerHTML}token&&(document.getElementById("login-screen").style.display="none",document.getElementById("dashboard").style.display="block",loadData()),document.getElementById("admin-password").addEventListener("keydown",function(t){"Enter"===t.key&&adminLogin()});
